"use strict";
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const pageNames={documents:"全部文档",papers:"论文资料",relations:"文档关系",trash:"回收站",files:"附件管理"};
const kindNames={note:"文档",project:"文档",paper:"论文资料",blog:"文档",log:"文档"};
const documentIcon=kind=>kind==="paper"?"book":"document";
const statusNames={inbox:"待整理",active:"进行中",done:"已完成",paused:"暂放"};
const icon=(name,cls="")=>WorkmoireIcons.render(name,cls);
function hydrateIcons(root=document){root.querySelectorAll("[data-icon]").forEach(node=>{node.innerHTML=icon(node.dataset.icon);});}
const state={authenticated:false,setup:false,page:"documents",current:null,baseline:null,editor:null,outline:null,toolbar:null,tagSavingId:null,tagDialogOpen:false,untagged:false,mode:localStorage.getItem("workmoire:editor-mode")==="read"?"read":"write",inspector:false,focus:false,items:[],total:0,cursor:null,query:"",tag:"",status:"",sort:"updated",listVersion:0,selectedIds:new Set(),assistant:null,assistantResult:"",saving:false,changes:0,draftTimer:null,draftError:false,outlineTimer:null,pendingFiles:[],pendingLinks:[],mediaType:"pdf",relationData:null,relationFocus:null,searchController:null};
const fields=["kind","title","summary","content","rich_content","tags","status","priority","due_date","entry_date","parent_id","pinned"];
const templates=[
  {key:"blank",name:"空白文档",caption:"直接记录内容，用标签组织文档",kind:"note",symbol:"document",title:"",tags:"",content:""},
  {key:"paper",name:"论文资料",caption:"上传 PDF，或从链接获取",kind:"paper",symbol:"book",title:"",tags:"论文",content:""}
];
function toast(message,error=false){const el=$("#toast");el.textContent=message;el.classList.toggle("is-error",error);el.classList.remove("is-hidden");clearTimeout(el.timer);el.timer=setTimeout(()=>el.classList.add("is-hidden"),error?6500:3200);}
async function api(path,options={}){
  const response=await fetch(path,{credentials:"same-origin",...options,headers:{...(options.body instanceof FormData?{}:{"Content-Type":"application/json"}),...options.headers}});
  const body=await response.json().catch(()=>({}));
  if(response.status===401&&state.authenticated){writeDraft();state.authenticated=false;$$('dialog[open]').forEach(d=>d.close());showAuthenticated(false);toast("登录已失效，请重新登录",true);}
  if(!response.ok){const error=new Error(body.error||"请求暂时失败，请重试");error.status=response.status;error.body=body;throw error;}
  return body;
}
const post=(path,payload)=>api(path,{method:"POST",body:JSON.stringify(payload)});
function showAuthenticated(value){$("#auth-view").classList.toggle("is-hidden",value);$("#app-view").classList.toggle("is-hidden",!value);}
function authMode(setup,token=false){state.setup=setup;$("#auth-title").textContent=setup?"创建账号":"登录 Workmoire";$("#auth-subtitle").textContent=setup?"创建用于访问文档和附件的唯一账号。":"使用已创建的账号登录。";$("#auth-submit").textContent=setup?"创建账号":"登录";$("#auth-confirm-row").classList.toggle("is-hidden",!setup);$("#auth-setup-token-row").classList.toggle("is-hidden",!setup||!token);$("#auth-confirm").required=setup;$("#auth-setup-token").required=setup&&token;$("#auth-password").autocomplete=setup?"new-password":"current-password";}
async function signedIn(username){state.authenticated=true;$("#account-name").textContent=username;$("#account-avatar").textContent=username.slice(0,1).toUpperCase();showAuthenticated(true);WorkmoireAbout.load(api);try{state.assistant=await api("/api/assistant/status");}catch{state.assistant=null;}await goPage("documents",true);refreshSidebar();}
async function boot(){try{const s=await api("/api/session");if(s.authenticated)await signedIn(s.username);else{showAuthenticated(false);authMode(s.setup,s.setup_token_required);}}catch(error){showAuthenticated(false);$("#auth-error").textContent=error.message;}}
$("#auth-form").onsubmit=async event=>{event.preventDefault();const button=$("#auth-submit");$("#auth-error").textContent="";const password=$("#auth-password").value;if(state.setup&&password!==$("#auth-confirm").value){$("#auth-error").textContent="两次密码不一致";return;}button.disabled=true;try{const payload={username:$("#auth-username").value.trim(),password};if(state.setup)payload.setup_token=$("#auth-setup-token").value;const session=await post(state.setup?"/api/setup":"/api/login",payload);$("#auth-password").value="";$("#auth-confirm").value="";$("#auth-setup-token").value="";await signedIn(session.username);}catch(error){$("#auth-error").textContent=error.message;}finally{button.disabled=false;}};
function snapshot(item){return Object.fromEntries(fields.map(key=>[key,key==="pinned"?Boolean(item?.[key]):key==="rich_content"?item?.[key]??null:item?.[key]??""]));}
function same(a,b){return JSON.stringify(snapshot(a))===JSON.stringify(snapshot(b));}
function metadata(){if(!state.current)return null;return {...state.current,title:$("#edit-title")?.value.trim()??state.current.title,summary:$("#edit-summary")?.value??state.current.summary,tags:state.current.tags,status:$("#edit-status")?.value??state.current.status,due_date:$("#edit-due")?.value??state.current.due_date,parent_id:$("#edit-parent")?.value?Number($("#edit-parent").value):null};}
function collect(){const item=metadata();return item?{...item,content:state.editor?.getValue()??item.content,rich_content:state.editor?.getNative()??item.rich_content??null}:null;}
function dirty(){if(!state.current||!state.editor)return false;const item=snapshot(metadata()),base=snapshot(state.baseline);return fields.some(key=>!["content","rich_content"].includes(key)&&item[key]!==base[key])||state.editor.hasChanges();}
function draftKey(item=state.current){return item?"workmoire:draft:"+item.kind+":"+(item.id||"new"):null;}
function readDraft(item){try{return JSON.parse(localStorage.getItem(draftKey(item))||"null");}catch{return null;}}
function clearDraft(item){try{localStorage.removeItem(draftKey(item));state.draftError=false;}catch{}}
function writeDraft(){clearTimeout(state.draftTimer);if(!state.current||!state.editor)return;if(state.editor.isComposing()){state.draftTimer=setTimeout(writeDraft,500);return;}try{if(!dirty()&&!state.pendingFiles.length&&!state.pendingLinks.length){clearDraft(state.current);return;}const draft=collect();localStorage.setItem(draftKey(draft),JSON.stringify({...draft,base_updated_at:state.current.updated_at||"",saved_at:new Date().toISOString(),pending_files:state.pendingFiles,pending_links:state.pendingLinks}));state.draftError=false;}catch{state.draftError=true;}updateSaveState();}
function changed(){state.changes++;updateCatalogTitle();clearTimeout(state.draftTimer);state.draftTimer=setTimeout(writeDraft,800);updateSaveState();clearTimeout(state.outlineTimer);state.outlineTimer=setTimeout(updateWordCount,350);}
function canLeave(){writeDraft();if(state.saving){toast("正在保存，请稍候");return false;}if(dirty()&&state.draftError){toast("本机草稿写入失败，请先保存文档再切换页面",true);return false;}return !dirty()||window.confirm("还有未保存的修改，已保留在本机草稿。确定离开吗？");}
function destroyEditor(){clearTimeout(state.draftTimer);clearTimeout(state.outlineTimer);state.toolbar?.destroy();state.toolbar=null;state.outline?.destroy();state.outline=null;state.editor?.destroy();state.editor=null;state.draftError=false;}
function resetCurrent(){destroyEditor();state.current=null;state.baseline=null;state.pendingFiles=[];state.pendingLinks=[];state.focus=false;document.body.classList.remove("focus-mode","has-document");}
async function goPage(page,force=false,options={}){
  if(!force&&!canLeave())return false;
  resetCurrent();state.page=page;state.query="";state.tag=options.tag||"";state.untagged=false;state.status="";state.cursor=null;state.selectedIds.clear();
  $("#page-heading").textContent=state.tag?"标签 · "+state.tag:pageNames[page];$$('.nav-item').forEach(el=>el.classList.toggle("is-active",el.dataset.page===page));setNavigation(false);
  try{if(page==="relations")await renderRelations();else if(page==="trash")await renderTrash();else if(page==="files")await renderFiles();else{renderWorkspace();await loadItems();renderList();renderEditor();}}catch(error){toast(error.message,true);}
  return true;
}
function renderWorkspace(){
  const paper=state.page==="papers";
  $("#page-content").innerHTML='<div class="document-workspace"><section class="document-list-panel"><div class="list-heading"><div><h1>'+(paper?"论文资料":"文档")+'</h1></div><button id="list-new" class="icon-button" title="'+(paper?"整理论文":"新建文档")+'" aria-label="'+(paper?"整理论文":"新建文档")+'">'+icon("plus")+'</button></div>'+(paper?'<button id="paper-quick-start" class="button paper-quick-start">'+icon("spark")+'上传 PDF 或链接</button>':"")+'<div class="list-search"><span>'+icon("search")+'</span><input id="list-search" type="search" placeholder="搜索这组文档…" aria-label="搜索当前文档"></div><div class="list-controls"><label class="select-all"><input type="checkbox" id="select-all" aria-label="选择当前列表全部文档"><span id="list-total">文档</span></label><select id="list-sort" aria-label="文档排序"><option value="updated">最近编辑</option><option value="title">按标题</option><option value="due">截止日期</option></select></div><div class="list-filter-row"><button id="tag-filter" class="list-filter-button">'+icon('tag')+'<span>标签</span>'+icon('chevron')+'</button><button id="clear-tag-filter" class="icon-button is-hidden" title="清除标签筛选" aria-label="清除标签筛选">'+icon('close')+'</button></div><div id="bulk-actions" class="bulk-actions is-hidden"><span id="bulk-count"></span><button id="bulk-done">标记完成</button><button id="bulk-trash" title="移入回收站">'+icon("trash")+'</button></div><div id="item-list" class="item-list"></div><div id="list-pagination" class="list-pagination"></div></section><section id="editor" class="editor-surface"></section></div>';
  $("#list-new").onclick=paper?openPaper:openTemplates;$("#paper-quick-start")?.addEventListener("click",openPaper);
  let timer;$("#list-search").oninput=event=>{const query=event.target.value;clearTimeout(timer);timer=setTimeout(async()=>{state.query=query;try{await loadItems();renderList();}catch(error){toast(error.message,true);}},180);};
  $("#list-sort").onchange=async event=>{state.sort=event.target.value;await loadItems();renderList();};$("#list-sort").value=state.sort;
  $("#select-all").onchange=event=>{const ids=state.items.map(x=>x.id);if(event.target.checked){if(ids.length>100){toast("一次最多选择 100 份文档",true);event.target.checked=false;return;}ids.forEach(id=>state.selectedIds.add(id));}else state.selectedIds.clear();renderList();};
  $("#tag-filter").onclick=()=>openTags(state.page=== "papers"?"paper":"");$("#clear-tag-filter").onclick=()=>applyTagFilter("");renderTagFilter();
  $("#bulk-done").onclick=()=>bulkAction("status");$("#bulk-trash").onclick=()=>bulkAction("trash");
}
async function loadItems(append=false){const version=++state.listVersion;const params=new URLSearchParams({limit:"50",sort:state.sort});if(state.page==="papers")params.set("kind","paper");if(state.query)params.set("q",state.query);if(state.tag)params.set("tag",state.tag);if(state.untagged)params.set("untagged","1");if(state.status)params.set("status",state.status);if(append&&state.cursor)params.set("cursor",state.cursor);const data=await api("/api/items?"+params);if(version!==state.listVersion)return;state.items=append?state.items.concat(data.items):data.items;state.total=data.total;state.cursor=data.next_cursor;if(!append)state.selectedIds.clear();}
function relative(value){if(!value)return "刚刚";const age=Date.now()-new Date(value);if(age<60000)return "刚刚";if(age<3600000)return Math.floor(age/60000)+" 分钟前";if(age<86400000)return Math.floor(age/3600000)+" 小时前";if(age<604800000)return Math.floor(age/86400000)+" 天前";return new Date(value).toLocaleDateString("zh-CN",{month:"short",day:"numeric"});}
function formatBytes(value){return value<1024?value+" B":value<1048576?(value/1024).toFixed(1)+" KB":(value/1048576).toFixed(1)+" MB";}
function plainPreview(item){return (item.summary||item.content_preview||"").replace(/[@#*_`\[\]>]/g,"").replace(/\s+/g," ").slice(0,90)||"暂无摘要或正文";}
function catalogTags(item){return WorkmoireTags.labels(item.tags,item.kind);}
function catalogRow(item,context=false){
  const rowKey=item.id||"draft",tags=catalogTags(item),title=item.title||"未命名文档",selected=state.current&&(state.current.id===item.id);
  return '<div class="document-row '+(selected?'is-selected ':'')+(context?'catalog-context-row':'')+'" data-row-key="'+rowKey+'" '+(!context?'data-result-row="true"':'')+'>'+(!context?'<label class="row-checkbox"><input type="checkbox" data-select="'+item.id+'" '+(state.selectedIds.has(item.id)?'checked':'')+' aria-label="选择 '+esc(title)+'"></label>':'')+
   '<button class="document-open" '+(item.id?'data-open="'+item.id+'"':'data-open-draft')+'><div class="document-row-title">'+icon(documentIcon(item.kind))+'<strong>'+esc(title)+'</strong></div><div class="document-row-summary"><p>'+esc(plainPreview(item))+'</p><time>'+(item.id?esc(relative(item.updated_at)):'未保存')+'</time></div></button>'+
   '<div class="row-actions"><button class="row-tags-button" data-manage-tags="'+rowKey+'" title="管理标签" aria-label="管理标签：'+esc(title)+'">'+icon('bookmark')+'</button><button class="pin-button '+(item.pinned?'is-pinned':'')+'" '+(item.id?'data-pin="'+item.id+'"':'disabled')+' title="'+(item.id?(item.pinned?'取消置顶':'置顶'):'保存后可置顶')+'" aria-label="'+(item.pinned?'取消置顶':'置顶')+'">'+icon('pin')+'</button></div>'+
   ((tags.length||item.task_total||item.status==='done')?'<div class="catalog-row-footer"><div class="catalog-row-tags">'+tags.slice(0,2).map(tag=>'<button class="catalog-tag bookmark-tag" data-tag-color="'+WorkmoireTags.color(tag)+'" data-filter-tag="'+esc(tag)+'" title="筛选标签：'+esc(tag)+'">'+esc(tag)+'</button>').join('')+(tags.length>2?'<button class="catalog-tags-more" data-manage-tags="'+rowKey+'" aria-label="查看全部 '+tags.length+' 个标签">+'+(tags.length-2)+'</button>':'')+'</div><div class="catalog-row-progress">'+(item.task_total?icon('task')+item.task_done+' / '+item.task_total:'')+(item.status==='done'?'<span>已完成</span>':'')+'</div></div>':'')+'</div>';
}
function updateCatalogTitle(){if(!state.current)return;const row=$('[data-row-key="'+(state.current.id||'draft')+'"]');if(row){const title=$("#edit-title")?.value||state.current.title||"未命名文档";row.querySelector('.document-row-title strong').textContent=title;row.querySelector('.row-tags-button').setAttribute('aria-label','管理标签：'+title);}}
function renderList(){
  const root=$("#item-list");if(!root)return;
  $("#list-total").textContent=state.total+" 份文档";
  const current=state.current?{...state.current,...(state.editor?metadata():{}),content_preview:state.current.summary||state.items.find(item=>item.id===state.current.id)?.content_preview||"点击继续编辑"}:null;
  const rows=state.items.map(item=>current?.id===item.id?{...item,...current}:item),context=current&&!rows.some(item=>item.id===current.id)?current:null;
  const lookup=new Map([...rows,...(context?[context]:[])].map(item=>[String(item.id||'draft'),item]));
  root.innerHTML=(context?'<div class="catalog-context-label">'+(context.id?'当前打开 · 不在本页列表中':'新文档草稿')+'</div>'+catalogRow(context,true)+(rows.length?'<div class="catalog-context-label">'+(state.tag||state.query||state.untagged?'筛选结果':'已保存的文档')+'</div>':''):'')+(rows.length?rows.map(item=>catalogRow(item)).join(''):context?'':'<div class="list-empty">'+icon('document')+'<strong>'+((state.query||state.tag||state.untagged)?'没有匹配的文档':'暂无文档')+'</strong><p>'+((state.tag||state.untagged)?'更换标签或清除筛选查看其他文档。':state.query?'尝试其他关键词。':state.page==='papers'?'点击“上传 PDF 或链接”添加论文。':'点击“新建文档”创建。')+'</p></div>');
  root.querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>openDocument(button.dataset.open));
  root.querySelector('[data-open-draft]')?.addEventListener('click',()=>document.body.classList.add('has-document'));
  root.querySelectorAll('[data-filter-tag]').forEach(button=>button.onclick=()=>applyTagFilter(button.dataset.filterTag));
  root.querySelectorAll('[data-manage-tags]').forEach(button=>button.onclick=()=>openRowTags(lookup.get(button.dataset.manageTags),button));
  root.querySelectorAll('[data-select]').forEach(input=>input.onchange=()=>{const id=Number(input.dataset.select);if(input.checked&&state.selectedIds.size>=100){input.checked=false;toast('一次最多选择 100 份文档',true);return;}if(input.checked)state.selectedIds.add(id);else state.selectedIds.delete(id);renderSelection();});
  root.querySelectorAll('[data-pin]').forEach(button=>button.onclick=async()=>{const item=lookup.get(button.dataset.pin);if(state.current?.id===item.id&&dirty()){toast('请先保存当前修改');return;}try{const result=await post('/api/items/'+item.id+'/pin',{pinned:!item.pinned});if(state.current?.id===item.id){state.current.pinned=result.item.pinned;state.current.updated_at=result.item.updated_at;state.baseline=snapshot(result.item);}await loadItems();renderList();}catch(error){toast(error.message,true);}});
  $("#list-pagination").innerHTML=state.cursor?'<button id="load-more" class="quiet-button">加载更多文档</button>':'';$("#load-more")?.addEventListener('click',async event=>{event.currentTarget.disabled=true;try{await loadItems(true);renderList();}catch(error){toast(error.message,true);}});renderSelection();
}
function rebaseTagDraft(before,after){
  const draft=readDraft(before);if(!draft||String(draft.base_updated_at||'')!==String(before.updated_at||''))return;
  try{localStorage.setItem(draftKey(before),JSON.stringify({...draft,tags:after.tags,base_updated_at:after.updated_at}));}catch{toast('标签已保存，本机草稿仍保留旧版本，可在打开文档后复制合并',true);}
}
function acceptTagUpdate(before,after){
  rebaseTagDraft(before,after);
  if(state.current?.id===before.id&&state.current.updated_at===before.updated_at){state.current.tags=after.tags;state.current.tags_list=after.tags_list;state.current.updated_at=after.updated_at;state.baseline.tags=after.tags;updateSaveState();if(dirty())writeDraft();}
}
async function refreshTagCatalogue(){if(!$("#item-list"))return;try{await loadItems();renderList();refreshSidebar();}catch{toast('标签已保存，列表暂时无法刷新，请稍后重试',true);}}
async function executeTagOperation(plan){
  if(state.saving||state.tagSavingId)throw new Error('文档正在保存，请稍后再操作标签');
  state.tagSavingId=state.current?.id||null;
  try{
    const result=await post('/api/tags/'+(plan.action==='delete'?'delete':'rename'),plan);
    for(const update of result.updates||[])acceptTagUpdate(update.before,update.after);
    if(state.current&&!state.current.id){const tags=WorkmoireTags.labels(state.current.tags,state.current.kind).flatMap(tag=>tag!==result.source?[tag]:result.action==='delete'?[]:[result.target]);state.current.tags=[...new Set(tags)].join(',');changed();writeDraft();}
    if(state.tag===result.source)state.tag=result.action==='delete'?'':result.target;
    await refreshTagCatalogue();return result;
  }finally{state.tagSavingId=null;}
}
async function openRowTags(row,anchor){
  if(!row||state.tagDialogOpen)return;if(state.saving&&state.current?.id===row.id){toast("正文正在保存，请稍候");return;}
  state.tagDialogOpen=true;let item;try{item=row.id&&state.current?.id!==row.id?(await api('/api/items/'+row.id)).item:{...row,tags:state.current?.id===row.id?state.current.tags:row.tags};}catch(error){state.tagDialogOpen=false;toast(error.message,true);return;}
  const draftTarget=!item.id?state.current:null;
  WorkmoireTags.edit({anchor,item,request:api,post,onExecute:executeTagOperation,onClose:()=>{state.tagDialogOpen=false;document.querySelector('[data-row-key="'+(item.id||'draft')+'"] .row-tags-button')?.focus();},
   async onApply(tags,base=item){
    if(!item.id){if(state.current!==draftTarget)throw new Error('文档已切换，请重新打开标签');if(state.current.tags!==tags){state.current.tags=tags;changed();writeDraft();renderList();}return {tags:state.current.tags,kind:state.current.kind};}
    if(state.saving&&state.current?.id===item.id)throw new Error('正文正在保存，请稍后再操作标签');
    state.tagSavingId=item.id;
    try{const result=(await post('/api/items/'+item.id+'/tags',{tags,base_updated_at:base.updated_at})).item;acceptTagUpdate(base,result);Object.assign(item,result);await refreshTagCatalogue();return result;}
    finally{state.tagSavingId=null;}
   }
  });
}

function renderSelection(){const count=state.selectedIds.size;$("#bulk-actions")?.classList.toggle("is-hidden",!count);if($("#bulk-count"))$("#bulk-count").textContent="已选 "+count;const all=$("#select-all");if(all){all.checked=Boolean(state.items.length&&state.items.every(x=>state.selectedIds.has(x.id)));all.indeterminate=!all.checked&&count>0;}}
async function bulkAction(action){if(!canLeave())return;const ids=[...state.selectedIds];if(!ids.length)return;if(action==="trash"&&!window.confirm("将选中的 "+ids.length+" 份文档移入回收站？"))return;try{await post("/api/items/bulk",{ids,action,status:"done"});if(state.current&&ids.includes(state.current.id)){if(action==="trash")resetCurrent();else{const data=await api("/api/items/"+state.current.id);state.current=data.item;state.baseline=snapshot(data.item);}renderEditor();}await loadItems();renderList();refreshSidebar();toast(action==="trash"?"已移入回收站":"已标记完成");}catch(error){toast(error.message,true);}}
async function openDocument(id,force=false){if(!force&&Number(id)===state.current?.id){document.body.classList.add("has-document");return;}if(!force&&!canLeave())return;try{const result=await api("/api/items/"+encodeURIComponent(id));if(!["documents","papers"].includes(state.page)){await goPage(result.item.kind==="paper"?"papers":"documents",true);}destroyEditor();state.current=result.item;state.baseline=snapshot(result.item);state.pendingFiles=[];state.pendingLinks=[];state.changes=0;renderList();renderEditor();}catch(error){toast(error.message,true);}}
function openTemplates(){if(!state.authenticated)return;setNavigation(false);$("#template-grid").innerHTML=templates.map(t=>'<button class="template-card" data-template="'+t.key+'"><span class="template-symbol">'+icon(t.symbol)+'</span><strong>'+t.name+'</strong><span>'+t.caption+'</span></button>').join("");$("#template-dialog").showModal();$$("[data-template]").forEach(button=>button.onclick=()=>{if(button.dataset.template==="paper"){$("#template-dialog").close();openPaper();}else newDocument(button.dataset.template);});}
async function newDocument(templateKey="blank",overrides={},leaveConfirmed=false){if(!leaveConfirmed&&!canLeave())return;const template=templates.find(t=>t.key===templateKey)||templates[0];const page=template.kind==="paper"?"papers":"documents";$("#template-dialog").close();if(!["documents","papers"].includes(state.page)||state.page!==page)await goPage(page,true);else writeDraft();destroyEditor();state.current={id:null,kind:template.kind,title:template.title,content:template.content,tags:template.tags,summary:"",status:"inbox",priority:2,pinned:false,parent_id:null,due_date:"",entry_date:"",updated_at:"",...overrides};if(state.current.kind!=="paper")state.current.kind="note";state.current.tags=WorkmoireTags.labels(state.current.tags,state.current.kind).join(",");state.baseline=snapshot({...state.current,title:"",content:"",tags:""});state.pendingFiles=[];state.pendingLinks=[];state.changes=0;state.mode="write";renderList();renderEditor(true);changed();}
