  root.innerHTML='<div class="document-editor"><header class="document-topline"><button id="back-to-list" class="quiet-button mobile-only">'+icon("back")+'文档</button><div class="document-location">'+icon(documentIcon(item.kind))+'<span>'+esc(kindNames[item.kind])+'</span><span class="quiet">/</span><span id="save-state" class="save-state" role="status"></span></div><div class="document-actions"><button id="assistant-content" class="icon-button" title="让 Codex 整理这份文档" aria-label="整理文档">'+icon("spark")+'</button><button id="focus-mode" class="icon-button" title="专注模式" aria-label="切换专注模式" aria-pressed="false">'+icon("expand")+'</button><button id="inspector-toggle" class="icon-button" title="文档信息与关联" aria-label="文档信息与关联" aria-expanded="'+state.inspector+'">'+icon("panel")+'</button><button id="share-document" class="button secondary small" title="分享文档">'+icon("share")+'分享</button><button id="save-content" class="button primary small">保存 <kbd>⌘ S</kbd></button></div></header><div id="draft-notice" class="draft-notice '+(!hasDraft?"is-hidden":"")+'">'+(hasDraft?(matching?'<span>这份文档有本机未保存的草稿。</span><button id="restore-draft">恢复草稿</button>':'<span>本机留有一份旧版本草稿，复制后可手动合并。</span><button id="copy-stale-draft">复制旧草稿</button>')+'<button id="dismiss-draft" aria-label="忽略草稿">'+icon("close")+'</button>':"")+'</div><div id="conflict-notice" class="draft-notice is-hidden"></div><div class="document-content-layout"><div class="writing-area"><div class="document-title-block"><textarea id="edit-title" class="editor-title" rows="1" maxlength="200" placeholder="未命名文档" aria-label="文档标题">'+esc(item.title)+'</textarea><div class="document-subline"><span id="document-word-count"></span><span>·</span><span>'+(item.updated_at?"编辑于 "+relative(item.updated_at):"尚未保存")+'</span><button id="outline-toggle" class="outline-toggle" type="button" aria-label="展开文档目录" aria-controls="document-outline" aria-expanded="false" hidden>'+icon('list')+'目录</button><div class="view-modes" aria-label="编辑视图"><button data-mode="write">'+icon("write")+'编辑</button><button data-mode="read">'+icon("read")+'阅读</button></div></div></div>'+editorTools()+'<div class="document-body"><div id="rich-editor" class="rich-editor-shell"></div><aside id="document-outline" class="outline-rail"></aside></div><footer class="editor-footer"><span id="editor-help">输入 / 插入内容 · Ctrl/⌘ S 保存</span><button id="document-link-button" class="quiet-button">'+icon("relations")+'链接文档</button></footer></div><aside id="doc-inspector" class="doc-inspector '+(!state.inspector?"is-hidden":"")+'"><div class="inspector-heading"><strong>文档信息</strong><button id="inspector-close" class="icon-button" aria-label="关闭文档信息">'+icon("close")+'</button></div><label class="field"><span>一句话摘要</span><textarea id="edit-summary" rows="3" maxlength="500" placeholder="输入文档摘要（最多 500 字）">'+esc(item.summary)+'</textarea></label><details class="inspector-details"><summary>状态与安排</summary><label class="field"><span>状态</span><select id="edit-status">'+Object.entries(statusNames).map(([v,n])=>'<option value="'+v+'" '+(item.status===v?"selected":"")+'>'+n+'</option>').join("")+'</select></label><label class="field"><span>截止日期</span><input id="edit-due" type="date" value="'+esc(item.due_date)+'"></label><label class="field"><span>上级文档</span><select id="edit-parent"><option value="">无上级文档</option>'+(item.parent_id?'<option selected value="'+item.parent_id+'">已关联上级文档</option>':"")+'</select></label></details><section class="inspector-section"><div class="section-label">关联文档 <button id="add-relation" title="链接文档" aria-label="链接文档">'+icon("plus")+'</button></div><div id="document-relations" class="document-relations"></div></section><section class="inspector-section"><div class="section-label">附件 <button id="add-attachment" title="上传附件" aria-label="上传附件">'+icon("plus")+'</button></div><div id="document-assets" class="document-assets"></div></section><details class="inspector-details"><summary>历史版本</summary><div id="document-history" class="document-history"></div></details><div class="inspector-bottom"><button id="export-markdown" class="quiet-button">导出 Markdown</button><button id="duplicate-document" class="quiet-button">另存副本</button><button id="delete-document" class="quiet-button danger">移入回收站</button></div></aside></div></div>';
  state.editor=WorkmoireEditor.mount($("#rich-editor"),{content:item.content,richContent:item.rich_content,baseline:state.baseline,onChange:changed,onSelection:syncEditorTools,command:editorCommand,upload:uploadAsset,openDocument,importPDF:importNativePDF,copy:copyText,editable:state.mode!=="read"});$("#edit-title").oninput=()=>{fitTitle();changed();};$("#edit-title").onkeydown=event=>{if(event.key==="Enter"){event.preventDefault();state.editor.focus();}};fitTitle();
