async function renderTrash(itemOffset=0,fileOffset=0){const data=await api("/api/trash?item_offset="+itemOffset+"&file_offset="+fileOffset);$("#page-content").innerHTML='<div class="standalone-page"><div class="standalone-heading"><div><h1>回收站</h1><p>误删的文档和附件可以在这里恢复。</p></div></div><div class="trash-grid">'+[["items","文档",data.items],["files","附件",data.files]].map(([type,label,rows])=>'<section class="plain-card"><div class="section-label">'+label+' · '+data.totals[type]+'</div>'+(rows.length?rows.map(item=>'<div class="trash-row"><div><strong>'+esc(item.title||item.name)+'</strong><small>'+esc(relative(item.deleted_at))+'</small></div><button class="button secondary small" data-trash-restore="'+type+':'+item.id+'">恢复</button><button class="quiet-button danger" data-trash-purge="'+type+':'+item.id+'">永久删除</button></div>').join(""):'<p class="empty-hint">这里是空的。</p>')+(data.next_offsets[type]!=null?'<button class="quiet-button" data-trash-more="'+type+'">加载更多</button>':"")+'</section>').join("")+'</div></div>';
  $$("[data-trash-restore]").forEach(button=>button.onclick=async()=>{const [type,id]=button.dataset.trashRestore.split(":");try{await post("/api/trash/"+type+"/"+id+"/restore",{});await renderTrash(itemOffset,fileOffset);refreshSidebar();toast("已恢复");}catch(error){toast(error.message,true);}});$$("[data-trash-purge]").forEach(button=>button.onclick=async()=>{if(!window.confirm("永久删除后无法恢复，确定继续吗？"))return;const [type,id]=button.dataset.trashPurge.split(":");try{await api("/api/trash/"+type+"/"+id,{method:"DELETE"});await renderTrash(itemOffset,fileOffset);toast("已永久删除");}catch(error){toast(error.message,true);}});$$("[data-trash-more]").forEach(button=>button.onclick=()=>renderTrash(button.dataset.trashMore==="items"?data.next_offsets.items:itemOffset,button.dataset.trashMore==="files"?data.next_offsets.files:fileOffset));
}
async function renderFiles(){const data=await api("/api/files?limit=200");$("#page-content").innerHTML='<div class="standalone-page"><div class="standalone-heading"><div><h1>附件管理</h1><p>图片、PDF 和其他附件。'+data.total+' 个文件 · '+formatBytes(data.total_bytes)+'</p></div></div><section class="plain-card file-manager">'+(data.files.length?data.files.map(file=>'<div class="managed-file"><a href="/files/'+file.id+'" target="_blank" rel="noopener">'+icon(file.content_type==="application/pdf"?"book":"document")+'<span><strong>'+esc(file.name)+'</strong><small>'+formatBytes(file.size)+(file.item_title?" · "+esc(file.item_title):" · 未关联文档")+'</small></span></a><button class="quiet-button" data-file-preview="'+file.id+'">打开</button><button class="quiet-button danger" data-file-trash="'+file.id+'">移入回收站</button></div>').join(""):'<p class="empty-hint">在文档中粘贴图片或上传 PDF，附件就会出现在这里。</p>')+'</section></div>';$$("[data-file-preview]").forEach(button=>button.onclick=()=>window.open("/files/"+button.dataset.filePreview+"?inline=1","_blank","noopener"));$$("[data-file-trash]").forEach(button=>button.onclick=async()=>{if(!window.confirm("将这个附件移入回收站？正文中的引用将暂时无法预览。"))return;try{await api("/api/files/"+button.dataset.fileTrash,{method:"DELETE"});await renderFiles();}catch(error){toast(error.message,true);}});}
let searchTimer,searchVersion=0;$("#global-search").oninput=event=>{clearTimeout(searchTimer);const query=event.target.value;searchTimer=setTimeout(()=>searchGlobal(query),160);};
async function searchGlobal(query){const version=++searchVersion,root=$("#search-results");state.searchController?.abort();if(!query.trim()){root.innerHTML='<p class="empty-hint">输入关键词开始搜索。</p>';return;}state.searchController=new AbortController();try{const data=await api("/api/search?limit=50&q="+encodeURIComponent(query),{signal:state.searchController.signal});if(version!==searchVersion)return;root.innerHTML=data.items.length||data.files.length?data.items.map(item=>'<button class="search-result" data-search-id="'+item.id+'">'+icon(documentIcon(item.kind))+'<span><strong>'+esc(item.title)+'</strong><p>'+esc(item.snippet||item.summary||"")+'</p><small>'+esc(kindNames[item.kind])+" · "+relative(item.updated_at)+'</small></span></button>').join("")+data.files.map(file=>'<a class="search-result" href="/files/'+file.id+'" target="_blank" rel="noopener">'+icon("document")+'<span><strong>'+esc(file.name)+'</strong><small>附件 · '+formatBytes(file.size)+'</small></span></a>').join(""):'<p class="empty-hint">没有找到匹配的内容。</p>';root.querySelectorAll("[data-search-id]").forEach(button=>button.onclick=async()=>{if(!canLeave())return;$("#search-dialog").close();await openDocument(button.dataset.searchId,true);});}catch(error){if(error.name!=="AbortError")root.innerHTML='<p class="error">'+esc(error.message)+'</p>';}}
function openSearch(){if(!state.authenticated)return;$("#search-dialog").showModal();$("#global-search").focus();}
function setNavigation(open){$(".sidebar").classList.toggle("is-open",open);$("#sidebar-backdrop").classList.toggle("is-hidden",!open);$("#mobile-menu").setAttribute("aria-expanded",String(open));}
function openAbout(){hideSettings();setNavigation(false);WorkmoireAbout.open(api);}
$("#about-button").onclick=openAbout;$("#app-version").onclick=openAbout;
function hideSettings(){$("#settings-menu").classList.add("is-hidden");$("#settings-button").setAttribute("aria-expanded","false");}
$("#settings-button").onclick=()=>{const open=$("#settings-menu").classList.toggle("is-hidden");$("#settings-button").setAttribute("aria-expanded",String(!open));};
$$('[data-settings-page]').forEach(button=>button.onclick=()=>{hideSettings();goPage(button.dataset.settingsPage);});
function download(path,name){hideSettings();const a=document.createElement("a");a.href=path;a.download=name;document.body.append(a);a.click();a.remove();}
$("#export-data").onclick=()=>download("/api/export","workmoire-export.json");$("#export-archive").onclick=()=>download("/api/export-archive","workmoire-archive.zip");
$("#import-data").onclick=()=>{hideSettings();$("#import-input").click();};$("#import-archive").onclick=()=>{hideSettings();$("#import-archive-input").click();};
$("#import-input").onchange=async event=>{const file=event.target.files[0];if(!file||!canLeave())return;try{const data=JSON.parse(await file.text());if(!window.confirm("追加导入 "+(data.items?.length||0)+" 份文档？已有内容不会被覆盖。"))return;const result=await post("/api/import",data);toast("已导入 "+result.imported_items+" 份文档");await goPage("documents",true);refreshSidebar();}catch(error){toast(error.message,true);}finally{event.target.value="";}};
$("#import-archive-input").onchange=async event=>{const file=event.target.files[0];if(!file||!canLeave())return;if(!window.confirm("追加导入归档中的文档和附件？已有内容不会被覆盖。"))return;const form=new FormData();form.append("file",file);try{const result=await api("/api/import-archive",{method:"POST",body:form});toast("已导入 "+result.imported_items+" 份文档及 "+result.imported_files+" 个附件");await goPage("documents",true);refreshSidebar();}catch(error){toast(error.message,true);}finally{event.target.value="";}};
$("#change-password").onclick=()=>{hideSettings();$("#password-error").textContent="";$("#password-dialog").showModal();};$("#password-form").onsubmit=async event=>{event.preventDefault();try{await post("/api/password",{old_password:$("#old-password").value,new_password:$("#new-password").value});$("#old-password").value="";$("#new-password").value="";$("#password-dialog").close();toast("密码已更新");}catch(error){$("#password-error").textContent=error.message;}};
$("#logout").onclick=async()=>{if(!canLeave())return;try{await post("/api/logout",{});hideSettings();resetCurrent();state.authenticated=false;showAuthenticated(false);authMode(false);}catch(error){toast(error.message,true);}};
$$('[data-close]').forEach(button=>button.onclick=()=>$("#"+button.dataset.close).close());
$$('dialog').forEach(dialog=>dialog.addEventListener("click",event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}));
$$('.nav-item').forEach(button=>button.onclick=()=>goPage(button.dataset.page));$("#new-document").onclick=openTemplates;$("#brand-home").onclick=event=>{event.preventDefault();goPage("documents");};$("#global-search-trigger").onclick=openSearch;$("#shortcuts-button").onclick=()=>{hideSettings();$("#shortcuts-dialog").showModal();};$("#tag-library-button").onclick=()=>{setNavigation(false);openTags();};$("#mobile-menu").onclick=()=>setNavigation(!$(".sidebar").classList.contains("is-open"));$("#sidebar-backdrop").onclick=()=>setNavigation(false);
$("#symbol-grid").innerHTML="α β γ δ ε θ λ μ π σ φ ψ ω Δ Σ Ω ∂ ∇ ∫ ∑ ∏ √ ∞ ≈ ≠ ≤ ≥ ± × ÷ ∈ ∉ ⊂ ⊆ ∪ ∩ ∅ ∀ ∃ ⇒ ⇔ → ← ↔ · … ✓ ✗".split(" ").map(s=>'<button type="button" data-symbol="'+s+'">'+s+'</button>').join("");$$("[data-symbol]").forEach(button=>button.onclick=()=>{state.editor?.insertText(button.dataset.symbol);$("#symbol-dialog").close();});
document.addEventListener("click",event=>{if(!event.target.closest("#settings-button,#settings-menu"))hideSettings();if(!event.target.closest(".insert-menu")){$$(".insert-menu").forEach(menu=>menu.open=false);}});
document.addEventListener("keydown",event=>{if(!state.authenticated||event.defaultPrevented||event.isComposing)return;const mod=event.ctrlKey||event.metaKey,key=event.key.toLowerCase(),dialog=$('dialog[open]');if(mod&&key==="k"){event.preventDefault();if(!dialog&&state.editor?.selection().text)editorCommand("link");else openSearch();}if(mod&&key==="f"&&state.editor&&!dialog){event.preventDefault();state.editor.showFind();}if(mod&&event.shiftKey&&key==="n"){event.preventDefault();openTemplates();}if(mod&&key==="s"&&state.current&&!dialog){event.preventDefault();saveDocument();}if(key==="escape"){hideSettings();setNavigation(false);$$(".insert-menu").forEach(menu=>menu.open=false);if(state.focus&&!dialog){state.focus=false;document.body.classList.remove("focus-mode");$("#focus-mode")?.setAttribute("aria-pressed","false");state.editor?.measure();}}});
window.addEventListener("beforeunload",event=>{if(dirty()){writeDraft();event.preventDefault();event.returnValue="";}});
async function serviceStatus(){try{const r=await fetch("/healthz",{cache:"no-store"});if(!r.ok)throw new Error();$("#service-status").classList.remove("is-offline");$("#service-status").title="服务在线";}catch{$("#service-status").classList.add("is-offline");$("#service-status").title="服务连接异常";}}
function collapseNavigation(collapsed){document.body.classList.toggle("navigation-collapsed",collapsed);const button=$("#navigation-toggle");button.setAttribute("aria-expanded",String(!collapsed));button.setAttribute("aria-label",collapsed?"展开侧边栏":"收起侧边栏");button.title=button.getAttribute("aria-label");try{localStorage.setItem("workmoire:navigation-collapsed",String(collapsed));}catch{}state.editor?.measure();}
$("#navigation-toggle").onclick=()=>collapseNavigation(!document.body.classList.contains("navigation-collapsed"));
try{collapseNavigation(localStorage.getItem("workmoire:navigation-collapsed")==="true");}catch{}
hydrateIcons();serviceStatus();setInterval(serviceStatus,60000);boot();

// Re-measure after local font subsets load, including multiline Chinese titles.
document.fonts?.addEventListener("loadingdone",()=>{fitTitle();state.editor?.measure();});

let layoutFrame;
window.addEventListener("resize",()=>{cancelAnimationFrame(layoutFrame);layoutFrame=requestAnimationFrame(()=>{fitTitle();$$(".insert-menu[open]").forEach(positionInsertMenu);state.editor?.measure();if(innerWidth>760)setNavigation(false);});});
